INSERT INTO guides (name, description, short_description, image, location_lat, location_lng, location_address, contact_phone, contact_email, contact_facebook, languages, specialties, rate, featured, is_active, created_at, updated_at)
VALUES
('Maria Santos', 'Licensed DOT-accredited tour guide with 10 years experience in Calbayog City. Expert in waterfall tours and cultural heritage sites. Fluent in English, Filipino, and Waray.', 'Expert waterfall tour guide', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330', 12.0680, 124.5965, 'City Proper, Calbayog City', '09171234567', 'maria.santos@calbayogtourism.com', 'https://facebook.com/mariasantosguide', ARRAY['English', 'Filipino', 'Waray'], ARRAY['Waterfalls', 'Heritage Sites', 'Cultural Tours'], '₱1,500/day', true, true, NOW(), NOW()),
('Jose Reyes', 'Adventure guide specializing in trekking, zipline, and outdoor activities. Knows all the hidden gems of Calbayog including off-the-beaten-path locations.', 'Adventure and trekking specialist', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d', 12.0750, 124.5850, 'Brgy. Tinaplacan, Calbayog City', '09181234567', 'jose.reyes@calbayogadventures.com', 'https://facebook.com/josereyesguide', ARRAY['English', 'Filipino'], ARRAY['Trekking', 'Zipline', 'Adventure Tours', 'Nature'], '₱1,800/day', true, true, NOW(), NOW()),
('Ana Cruz', 'Family-friendly tour guide perfect for groups with children. Specializes in beach tours, educational trips, and safe family adventures around Calbayog.', 'Family tour specialist', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80', 12.0550, 124.6100, 'Brgy. Mawacat, Calbayog City', '09191234567', 'ana.cruz@familytours.com', 'https://facebook.com/anacruzguide', ARRAY['English', 'Filipino', 'Waray'], ARRAY['Beach Tours', 'Family Trips', 'Educational Tours'], '₱1,200/day', false, true, NOW(), NOW()),
('Ricardo Tan', 'Local historian and cultural guide. Deep knowledge of Calbayogs history, traditions, and local stories. Perfect for heritage and cultural immersion tours.', 'Cultural and heritage expert', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e', 12.0695, 124.5980, 'City Proper, Calbayog City', '09201234567', 'ricardo.tan@calbayogheritage.com', 'https://facebook.com/ricardotanguide', ARRAY['English', 'Filipino', 'Waray'], ARRAY['Heritage', 'History', 'Cultural Immersion', 'Local Stories'], '₱1,500/day', true, true, NOW(), NOW()),
('Elena Martinez', 'Photography guide who knows the best spots for stunning photos in Calbayog. Expert in waterfall photography, sunset spots, and scenic locations.', 'Photography tour guide', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2', 12.0320, 124.6250, 'Brgy. Malajog, Calbayog City', '09211234567', 'elena.martinez@phototours.com', 'https://facebook.com/elenamartinezguide', ARRAY['English', 'Filipino'], ARRAY['Photography', 'Scenic Spots', 'Sunset Tours', 'Waterfalls'], '₱1,600/day', false, true, NOW(), NOW())
